def transform(grid):
    h, w = len(grid), len(grid[0])

    # The grid color that forms the full separator lines.
    colors = set(v for row in grid for v in row)
    sep = max(colors, key=lambda color:
              sum(all(v == color for v in row) for row in grid) +
              sum(all(grid[r][c] == color for r in range(h)) for c in range(w)))

    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]

    # The ordinary cell background is the most common non-separator color.
    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for i in range(len(row_bounds) - 1):
        out_row = []
        for j in range(len(col_bounds) - 1):
            marks = 0
            for r in range(row_bounds[i] + 1, row_bounds[i + 1]):
                for c in range(col_bounds[j] + 1, col_bounds[j + 1]):
                    if grid[r][c] != sep and grid[r][c] != background:
                        marks += 1
            out_row.append(1 if marks == 2 else background)
        result.append(out_row)
    return result
